window.addEventListener('beforeunload',e=>{if(S.capture||pendingWrites>0||[...pending.values()].some(p=>p.changed||p.promise||p.error)){e.preventDefault();e.returnValue='';}});
window.addEventListener('offline',()=>toast(tr(isLocal()?'脱机模式：记录与录音仅保存到本机。':'连接已断开。请保留当前页面，恢复连接后再保存。'),!isLocal()));
