async function installApp(){const event=installEvent;if(!event)return {outcome:'dismissed'};installEvent=null;try{await event.prompt();return await event.userChoice;}finally{easyBinding?.refresh();}}
function bindEasyEntry(){easyBinding?.dispose();easyBinding=bindEasyStart($('#app'),{language,installAvailable:()=>!!installEvent,onInstall:installApp});}
document.addEventListener('visibilitychange',()=>{if(document.hidden&&S.capture)toast(tr('请保持录音页面在前台，锁屏可能中断采集。'),true);});
async function init(){try{if(await bootOffline()){authScreen(await accountStatus(device.mode));return;}const status=await json('/status');if(status.initialized){try{const session=await json('/session');S.csrf=session.csrf;S.workspace=session.workspace;await reload();render();return;}catch{}}authScreen(status.initialized);}catch(e){$('#app').innerHTML=ui`<div class="loading"><h2>暂时无法连接工作区</h2><p>${esc(e.message)}</p><p>请使用支持加密存储的普通浏览器窗口，并先完成离线资源准备。</p><button class="btn" id="retry-init">重新连接</button></div>`;$('#retry-init').onclick=init;$('#app .loading').insertAdjacentHTML('beforeend',authExtras());}}
setupOfflineUI({auth:authScreen,recording:()=>!!S.capture,notice:toast,render,download,locked:()=>{clearSessionView();S.records=[];S.selected=null;S.csrf='';P.open.clear();pending.clear();clearAudio();$('#floating-tools')?.remove();authScreen(true);},enter:async workspace=>{S.workspace=workspace;S.csrf='device';S.records=[];S.selected=null;S.view='dashboard';pending.clear();P.open.clear();await reload();render();},refresh:async()=>{await reload();render();}});
