setupUpdates({translate:tr,flush,recording:()=>!!S.capture,busy:()=>updateActions>0||pendingWrites>0||isOfflineBusy()||!!document.querySelector('dialog[open]'),saved:()=>![...pending.values()].some(p=>p.changed||p.promise||p.error)});
init();
